#!/usr/bin/env python3
"""calc: a tiny compiler that translates .calc programs to Python.

Grammar:
    program   := statement*
    statement := 'print' expr
    expr      := term (('+' | '-') term)*
    term      := atom (('*' | '/') atom)*
    atom      := NUMBER | '(' expr ')'
"""
import sys


def tokenize(src):
    tokens = []
    i = 0
    while i < len(src):
        c = src[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < len(src) and src[j].isdigit():
                j += 1
            tokens.append(('NUM', int(src[i:j])))
            i = j
        elif src[i:i + 5] == 'print':
            tokens.append(('PRINT', 'print'))
            i += 5
        elif c in '+-*/()':
            tokens.append(('OP', c))
            i += 1
        else:
            raise SyntaxError(f'unexpected character {c!r} at offset {i}')
    return tokens


class Parser:
    def __init__(self, tokens):
        self.toks = tokens
        self.pos = 0

    def peek(self):
        return self.toks[self.pos] if self.pos < len(self.toks) else None

    def advance(self):
        tok = self.peek()
        self.pos += 1
        return tok

    def parse_program(self):
        stmts = []
        while self.peek():
            stmts.append(self.parse_statement())
        return stmts

    def parse_statement(self):
        tok = self.advance()
        if tok is None or tok[0] != 'PRINT':
            raise SyntaxError(f"expected 'print', got {tok}")
        return f'print({self.parse_expr()})'

    def parse_expr(self):
        node = self.parse_term()
        while self.peek() in (('OP', '+'), ('OP', '-')):
            op = self.advance()[1]
            node = f'({node} {op} {self.parse_term()})'
        return node

    def parse_term(self):
        node = self.parse_atom()
        while self.peek() in (('OP', '*'), ('OP', '/')):
            op = self.advance()[1]
            node = f'({node} {op} {self.parse_atom()})'
        return node

    def parse_atom(self):
        tok = self.advance()
        if tok is None:
            raise SyntaxError('unexpected end of input')
        if tok[0] == 'NUM':
            return str(tok[1])
        if tok == ('OP', '('):
            node = self.parse_expr()
            if self.advance() != ('OP', ')'):
                raise SyntaxError("expected ')'")
            return node
        raise SyntaxError(f'unexpected token {tok}')


def compile_source(src):
    return '\n'.join(Parser(tokenize(src)).parse_program()) + '\n'


def main():
    if len(sys.argv) != 3:
        print(f'usage: {sys.argv[0]} <input.calc> <output.py>', file=sys.stderr)
        return 2
    with open(sys.argv[1]) as f:
        code = compile_source(f.read())
    with open(sys.argv[2], 'w') as f:
        f.write(code)
    return 0


if __name__ == '__main__':
    sys.exit(main())
